flow=[("08:05","يُبلغ عميل عبر واتساب أن مكيّف الهواء لا يبرّد."),("08:06","يتلقى الأسئلة الأساسية ويرسل صورة للجهاز."),("08:10","يُسنَد البلاغ إلى فني المنطقة مع كل المعلومات."),("11:40","يتلقى العميل إشعارًا: سيصل الفني بعد عشرين دقيقة."),("12:30","يُغلق الفني أمر العمل على الهاتف ويوقّع العميل."),("12:31","يصل أمر العمل إلى المكتب جاهزًا للفوترة.")],
